// Parts of the newer chart types (chartex), generated by code, laid out as
// Excel writes them ([MS-ODRAWXML] 2.24): the data of the chart by number
// (<cx:chartData>), the series with their layout (<cx:layoutPr>), the axes;
// and the frames that show such a part, in the alternate content Excel and
// Word wrap them in, with the fallback older versions show.

import { ZipArchive } from '../src/zip';
import { NS_A, OFFICE_THEME } from './chart-fixtures';
import { parseChartEx } from '../src/formats/xlsx/chartex';
import { parseXml } from '../src/xml';
import type { Chart } from '../src/model/sheet/chart';

export const NS_CX = 'http://schemas.microsoft.com/office/drawing/2014/chartex';
export const NS_CX1 = 'http://schemas.microsoft.com/office/drawing/2015/9/8/chartex';
const NS_REL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';
const NS_PKG_REL = 'http://schemas.openxmlformats.org/package/2006/relationships';
const NS_MC = 'http://schemas.openxmlformats.org/markup-compatibility/2006';
export const CHARTEX_REL = 'http://schemas.microsoft.com/office/2014/relationships/chartEx';
export const CHARTEX_TYPE = 'application/vnd.ms-office.chartex+xml';
const XML = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';

const escape = (text: string) => text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const pts = (values: (string | number | null)[]) => values.map((value, i) => (value === null ? '' : `<cx:pt idx="${i}">${escape(String(value))}</cx:pt>`)).join('');

/** A dimension of texts: `levels` from the leaves outwards, each with one name per point. */
export const strDim = (formula: string | undefined, levels: (string | null)[][], type = 'cat', dir = '') =>
  `<cx:strDim type="${type}">${formula !== undefined ? `<cx:f${dir ? ` dir="${dir}"` : ''}>${escape(formula)}</cx:f>` : ''}` +
  levels.map((level) => `<cx:lvl ptCount="${level.length}">${pts(level)}</cx:lvl>`).join('') +
  '</cx:strDim>';

/** A dimension of numbers. */
export const numDim = (formula: string | undefined, values: (number | null)[], type = 'val', formatCode = 'General') =>
  `<cx:numDim type="${type}">${formula !== undefined ? `<cx:f>${escape(formula)}</cx:f>` : ''}<cx:lvl ptCount="${values.length}" formatCode="${escape(formatCode)}">${pts(values)}</cx:lvl></cx:numDim>`;

export const data = (id: number, inner: string) => `<cx:data id="${id}">${inner}</cx:data>`;

export interface CxSeries {
  layout: string;
  dataId?: number;
  /** Elements inside <cx:layoutPr>. */
  layoutPr?: string;
  /** Further children: cx:tx, cx:spPr, cx:dataPt, cx:dataLabels. */
  inner?: string;
  axes?: number[];
  attrs?: string;
  formatIdx?: number;
}

export const series = (spec: CxSeries) =>
  `<cx:series layoutId="${spec.layout}"${spec.formatIdx !== undefined ? ` formatIdx="${spec.formatIdx}"` : ''}${spec.attrs ? ` ${spec.attrs}` : ''}>` +
  (spec.inner || '') +
  (spec.dataId !== undefined ? `<cx:dataId val="${spec.dataId}"/>` : '') +
  (spec.layoutPr !== undefined ? `<cx:layoutPr>${spec.layoutPr}</cx:layoutPr>` : '') +
  (spec.axes || []).map((id) => `<cx:axisId val="${id}"/>`).join('') +
  '</cx:series>';

/** The name of a series, as text and (with a formula) read from a cell. */
export const seriesName = (text: string, formula?: string) => `<cx:tx><cx:txData>${formula ? `<cx:f>${escape(formula)}</cx:f>` : ''}<cx:v>${escape(text)}</cx:v></cx:txData></cx:tx>`;

export const catAxis = (id = 0, inner = '<cx:tickLabels/>', gap?: string) => `<cx:axis id="${id}"><cx:catScaling${gap !== undefined ? ` gapWidth="${gap}"` : ''}/>${inner}</cx:axis>`;
export const valAxis = (id = 1, inner = '<cx:majorGridlines/><cx:tickLabels/>', scaling = '') => `<cx:axis id="${id}"><cx:valScaling${scaling ? ` ${scaling}` : ''}/>${inner}</cx:axis>`;

export interface CxChart {
  data: string;
  series: string;
  axes?: string;
  title?: string;
  legend?: string;
  /** The namespace of the root; that of the newer chart parts by default. */
  ns?: string;
  /** Children of the root after <cx:chart>. */
  after?: string;
}

export const cxTitle = (text: string) => `<cx:title pos="t" align="ctr" overlay="0"><cx:tx><cx:txData><cx:v>${escape(text)}</cx:v></cx:txData></cx:tx></cx:title>`;

/** A whole part of a newer chart type. */
export const chartExXml = (spec: CxChart) =>
  `${XML}<cx:chartSpace xmlns:a="${NS_A}" xmlns:r="${NS_REL}" xmlns:cx="${spec.ns || NS_CX}">` +
  `<cx:chartData>${spec.data}</cx:chartData><cx:chart>${spec.title || ''}<cx:plotArea><cx:plotAreaRegion>${spec.series}</cx:plotAreaRegion>${spec.axes || ''}</cx:plotArea>${spec.legend || ''}</cx:chart>${spec.after || ''}</cx:chartSpace>`;

/** The model of a part given as XML; undefined for one that is not drawn. */
export function readChartEx(xml: string, theme: string[] = OFFICE_THEME): Chart | undefined {
  return parseChartEx(parseXml(xml).root, theme);
}

// ----------------------------------------------------------- the kinds, ready-made

export const CATS = ['Start', 'Q1', 'Q2', 'Q3', 'End'];

/** A waterfall of five points over Sayfa1!A2:B6, the first and the last totals. */
export const waterfallXml = (values: number[] = [100, 20, -50, 30, 100], extra = '') =>
  chartExXml({
    data: data(0, strDim('Sayfa1!$A$2:$A$6', [CATS]) + numDim('Sayfa1!$B$2:$B$6', values)),
    series: series({ layout: 'waterfall', dataId: 0, inner: seriesName('Akış', 'Sayfa1!$B$1') + extra, layoutPr: '<cx:subtotals><cx:idx val="0"/><cx:idx val="4"/></cx:subtotals>', axes: [0, 1] }),
    axes: catAxis(0, '<cx:tickLabels/>', '0.5') + valAxis(1),
    title: cxTitle('Nakit'),
    legend: '<cx:legend pos="t" align="ctr" overlay="0"/>',
  });

/** A treemap of three levels. */
export const treemapXml = (layout = 'treemap', layoutPr = '<cx:parentLabelLayout val="overlapping"/>') =>
  chartExXml({
    data: data(
      0,
      strDim('Sayfa1!$A$2:$C$7', [
        ['a1', 'a2', 'b1', 'b2', 'c1', 'c2'],
        ['A', 'A', 'B', 'B', 'C', 'C'],
        ['Kök', 'Kök', 'Kök', 'Kök', 'Diğer', 'Diğer'],
      ]) + numDim('Sayfa1!$D$2:$D$7', [10, 20, 30, 5, 15, 20], 'size'),
    ),
    series: series({ layout, dataId: 0, inner: '<cx:dataLabels pos="inEnd"><cx:visibility seriesName="0" categoryName="1" value="0"/></cx:dataLabels>', layoutPr }),
  });

// ------------------------------------------------------------------- frames and packages

const DRAWING_NS = 'xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing"';

/** The frame of a chart of a newer type in a drawing of a sheet, as Excel writes it: in alternate content with a text box as the fallback. */
export const chartExFrame = (rel: string, name = 'Chart 1', fallbackText = 'This chart isn’t available in your version of Excel.') =>
  `<mc:AlternateContent xmlns:mc="${NS_MC}"><mc:Choice xmlns:cx1="${NS_CX1}" Requires="cx1">` +
  `<xdr:graphicFrame macro=""><xdr:nvGraphicFramePr><xdr:cNvPr id="2" name="${name}"/><xdr:cNvGraphicFramePr/></xdr:nvGraphicFramePr>` +
  '<xdr:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/></xdr:xfrm>' +
  `<a:graphic><a:graphicData uri="${NS_CX}"><cx:chart xmlns:cx="${NS_CX}" xmlns:r="${NS_REL}" r:id="${rel}"/></a:graphicData></a:graphic></xdr:graphicFrame>` +
  '</mc:Choice><mc:Fallback>' +
  '<xdr:sp macro="" textlink=""><xdr:nvSpPr><xdr:cNvPr id="3" name="Fallback"/><xdr:cNvSpPr><a:spLocks noTextEdit="1"/></xdr:cNvSpPr></xdr:nvSpPr>' +
  '<xdr:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="4572000" cy="2743200"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom><a:solidFill><a:prstClr val="white"/></a:solidFill></xdr:spPr>' +
  `<xdr:txBody><a:bodyPr/><a:lstStyle/><a:p><a:r><a:rPr lang="en-US" sz="1100"/><a:t>${escape(fallbackText)}</a:t></a:r></a:p></xdr:txBody></xdr:sp>` +
  '</mc:Fallback></mc:AlternateContent>';

/** A two-cell anchor around `inner`. */
export const anchor = (inner: string, from: [number, number] = [3, 1], to: [number, number] = [10, 16]) =>
  `<xdr:twoCellAnchor><xdr:from><xdr:col>${from[0]}</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>${from[1]}</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:from>` +
  `<xdr:to><xdr:col>${to[0]}</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>${to[1]}</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:to>${inner}<xdr:clientData/></xdr:twoCellAnchor>`;

/** The style and colour parts Excel writes beside a part of a newer type: never read, always kept. */
export const STYLE_PART = `${XML}<cs:chartStyle xmlns:cs="http://schemas.microsoft.com/office/drawing/2012/chartStyle" xmlns:a="${NS_A}" id="410"/>`;
export const COLORS_PART = `${XML}<cs:colorStyle xmlns:cs="http://schemas.microsoft.com/office/drawing/2012/chartStyle" xmlns:a="${NS_A}" meth="cycle" id="10"><a:schemeClr val="accent1"/></cs:colorStyle>`;

/**
 * Adds parts of newer chart types to a workbook made by chartWorkbook(): each becomes
 * xl/charts/chartEx<n>.xml, related to the drawing of the first sheet as "rIdX<n>", with its
 * style and colour parts beside it.
 */
export async function addChartEx(bytes: Uint8Array, parts: string[]): Promise<Uint8Array> {
  const zip = ZipArchive.read(bytes);
  const text = async (name: string) => new TextDecoder().decode(await zip.read(name));
  let rels = await text('xl/drawings/_rels/drawing1.xml.rels');
  let types = await text('[Content_Types].xml');
  parts.forEach((xml, i) => {
    const n = i + 1;
    zip.set(`xl/charts/chartEx${n}.xml`, new TextEncoder().encode(xml));
    zip.set(`xl/charts/style${n}.xml`, new TextEncoder().encode(STYLE_PART));
    zip.set(`xl/charts/colors${n}.xml`, new TextEncoder().encode(COLORS_PART));
    zip.set(
      `xl/charts/_rels/chartEx${n}.xml.rels`,
      new TextEncoder().encode(
        `${XML}<Relationships xmlns="${NS_PKG_REL}"><Relationship Id="rId1" Type="http://schemas.microsoft.com/office/2011/relationships/chartStyle" Target="style${n}.xml"/>` +
          `<Relationship Id="rId2" Type="http://schemas.microsoft.com/office/2011/relationships/chartColorStyle" Target="colors${n}.xml"/></Relationships>`,
      ),
    );
    rels = rels.replace('</Relationships>', `<Relationship Id="rIdX${n}" Type="${CHARTEX_REL}" Target="../charts/chartEx${n}.xml"/></Relationships>`);
    types = types.replace(
      '</Types>',
      `<Override PartName="/xl/charts/chartEx${n}.xml" ContentType="${CHARTEX_TYPE}"/>` +
        `<Override PartName="/xl/charts/style${n}.xml" ContentType="application/vnd.ms-office.chartstyle+xml"/>` +
        `<Override PartName="/xl/charts/colors${n}.xml" ContentType="application/vnd.ms-office.chartcolorstyle+xml"/></Types>`,
    );
  });
  zip.set('xl/drawings/_rels/drawing1.xml.rels', new TextEncoder().encode(rels));
  zip.set('[Content_Types].xml', new TextEncoder().encode(types));
  return zip.write();
}

export { DRAWING_NS };

// --------------------------------------------------------------------------- Word

const PX = 9525;

/** A run that holds a chart of a newer type in its line, as Word writes it: in alternate content, with a picture as the fallback. */
export const chartExRun = (rel: string, width: number, height: number, fallbackRel?: string) =>
  `<w:r><mc:AlternateContent xmlns:mc="${NS_MC}"><mc:Choice Requires="cx1">` +
  `<w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0"><wp:extent cx="${width * PX}" cy="${height * PX}"/><wp:docPr id="9" name="Chart 9"/><wp:cNvGraphicFramePr/>` +
  `<a:graphic xmlns:a="${NS_A}"><a:graphicData uri="${NS_CX}"><cx:chart xmlns:cx="${NS_CX}" xmlns:r="${NS_REL}" r:id="${rel}"/></a:graphicData></a:graphic></wp:inline></w:drawing>` +
  '</mc:Choice><mc:Fallback>' +
  (fallbackRel
    ? `<w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0"><wp:extent cx="${width * PX}" cy="${height * PX}"/><wp:docPr id="10" name="Picture 10"/><wp:cNvGraphicFramePr/>` +
      `<a:graphic xmlns:a="${NS_A}"><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture">` +
      `<pic:nvPicPr><pic:cNvPr id="0" name="fallback.png"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip xmlns:r="${NS_REL}" r:embed="${fallbackRel}"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill>` +
      `<pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="${width * PX}" cy="${height * PX}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing>`
    : '<w:t>fallback</w:t>') +
  '</mc:Fallback></mc:AlternateContent></w:r>';

/** The namespaces the document part of a Word file with charts of newer types declares on its root. */
export const CX_ROOT_ATTRS = `xmlns:mc="${NS_MC}" xmlns:cx1="${NS_CX1}" mc:Ignorable="cx1"`;
